//! The reference model the twin runs: the Kafka contract's `cluster` spec
//! handler, generated by LawSpec, over a state the twin owns.
//!
//! Each operation of `Broker` is a method of `ClusterModel` (written by
//! `build.rs` from the generated handler) that runs the contract's checked
//! definition and keeps the next state. A request the contract refuses gives
//! `Failure::Kafka` with the `KafkaError` the definition raised.
//! ref:DEC-embed-generated-model

use lawspec_example::lawspec_definitions::typed;
use lawspec_example::lawspec_runtime as ls;

pub use lawspec_example::lawspec_data as data;

/// Why an operation of the model gave no result.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Failure {
    /// The contract refused the request with this error.
    Kafka(data::KafkaError),
    /// The generated code failed; this is a defect, never a refusal.
    Model(String),
}

impl std::fmt::Display for Failure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Failure::Kafka(e) => write!(f, "{e:?}"),
            Failure::Model(m) => write!(f, "model failure: {m}"),
        }
    }
}

/// The Kafka contract's reference model, with its state.
#[derive(Clone)]
pub struct ClusterModel {
    state: typed::BrokerState,
}

impl Default for ClusterModel {
    fn default() -> Self {
        Self::start()
    }
}

/// Runs one generated definition, giving a raised `KafkaError` back as a value.
fn run<T>(body: impl FnOnce() -> ls::Result<T>) -> Result<T, Failure> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(body)) {
        Ok(Ok(value)) => Ok(value),
        Ok(Err(message)) => Err(Failure::Model(message)),
        Err(payload) => match payload.downcast::<ls::Failure>() {
            Ok(failure) => {
                let typed_error = <typed::KafkaError as ls::fast::Dyn>::from_dyn(failure.value.clone())
                    .map_err(|e| Failure::Model(format!("{} raised {:?}: {e}", failure.ability, failure.value)))?;
                Err(Failure::Kafka(ls::fast::Public::to_native(&typed_error)))
            }
            Err(other) => Err(Failure::Model(panic_text(&other))),
        },
    }
}

fn panic_text(payload: &Box<dyn std::any::Any + Send>) -> String {
    if let Some(s) = payload.downcast_ref::<String>() {
        s.clone()
    } else if let Some(s) = payload.downcast_ref::<&str>() {
        s.to_string()
    } else {
        "a panic in the generated model".into()
    }
}

impl ClusterModel {
    /// The model in its start state: the contract's `model.emptyBroker`.
    pub fn start() -> Self {
        let state = Self::start_state().expect("the contract's start state");
        Self { state }
    }

    /// The whole state, in the generated native types. It costs a copy of
    /// every record, so `inspect` uses it and requests do not.
    pub fn snapshot(&self) -> data::BrokerState {
        ls::fast::Public::to_native(&self.state)
    }

    /// The topics and their partition counts, without copying any log.
    pub fn topics(&self) -> std::collections::BTreeMap<String, i32> {
        let typed::BrokerStateNode::BrokerState(topics, ..) = &*self.state.0;
        ls::fast::Public::to_native(topics)
    }

    /// The group ids the model holds, without copying any log.
    pub fn group_ids(&self) -> Vec<String> {
        let typed::BrokerStateNode::BrokerState(_, _, _, _, _, groups, _) = &*self.state.0;
        let native: std::collections::BTreeMap<String, data::Group> = ls::fast::Public::to_native(groups);
        native.into_keys().collect()
    }
}

#[allow(non_snake_case)]
mod generated {
    use super::*;
    include!(concat!(env!("OUT_DIR"), "/cluster_model.rs"));
}

impl ClusterModel {
    /// The producer id and epoch a transactional id maps to, without
    /// copying any log.
    pub fn producer_of(&self, transactional_id: &str) -> Option<(i64, i16)> {
        let typed::BrokerStateNode::BrokerState(_, _, producers, ids, ..) = &*self.state.0;
        let ids: std::collections::BTreeMap<String, i64> = ls::fast::Public::to_native(ids);
        let pid = *ids.get(transactional_id)?;
        let producers: std::collections::BTreeMap<i64, data::ProducerEntry> = ls::fast::Public::to_native(producers);
        producers.get(&pid).map(|p| (pid, p.epoch))
    }
}
